head.script:
scwin.onpageload = function() {
    // 초기 comp 생성
    scwin.comp_init();   	
};

// comp 생성
scwin.comp_init = async function () {
    let strTarget = '';
    let strGroup = '';
    let strTextbox = '';

    let strNameSpace = 'xmlns="http://www.w3.org/1999/xhtml" xmlns:ev="http://www.w3.org/2001/xml-events" xmlns:w2="http://www.inswave.com/websquare" xmlns:xf="http://www.w3.org/2002/xforms"';

    strTarget += '<w2:gridLayout '+strNameSpace+' style="width:400px; height:200px;" gridTemplateColumns="1fr 1fr;" gridTemplateRows="1fr 1fr 1fr;" gridColumnGap="1px;" gridRowGap="1px;" gridColumn="1:1:1:2:2:2;" gridRow="1:2:3:1:2:3;" rowShow="1:1:1:1:1:1;">';
    strTarget += '</w2:gridLayout>';    

    scwin.gridLayout1 = await $p.dynamicCreate(
        "gridLayout1",
        "gridLayout",
        strTarget,
        main_group
    );

    strGroup += '<xf:group '+strNameSpace+' style="background-color: silver;">';
    strGroup += '</xf:group>';

    scwin.group1 = await $p.dynamicCreate(
        "group1",
        "group",
        strGroup,
        gridLayout1
    );

    strTextbox += '<w2:textbox '+strNameSpace+' id="" label="label1" style="width:150px; height:23px; "></w2:textbox>';

    scwin.textbox1 = await $p.dynamicCreate(
        "textbox1",
        "textbox",
        strTextbox,
        group1
    );
}
